Proceso ContarMayoresQuePromedio
    Dimension datos[3, 3] Como Entero;
    Definir fila Como Entero;
    Definir columna Como Entero;
    Definir suma Como Entero;
    Definir promedio Como Real;
    Definir contador Como Entero;
    Para fila <- 0 Hasta 2 Con Paso 1 Hacer
        Para columna <- 0 Hasta 2 Con Paso 1 Hacer
            Leer datos[fila, columna];
        FinPara
    FinPara
    suma <- 0;
    Para fila <- 0 Hasta 2 Con Paso 1 Hacer
        Para columna <- 0 Hasta 2 Con Paso 1 Hacer
            suma <- suma + datos[fila, columna];
        FinPara
    FinPara
    promedio <- suma / 9;
    contador <- 0;
    Para fila <- 0 Hasta 2 Con Paso 1 Hacer
        Para columna <- 0 Hasta 2 Con Paso 1 Hacer
            Si datos[fila, columna] > promedio Entonces
                contador <- contador + 1;
            FinSi
        FinPara
    FinPara
    Escribir contador;
FinProceso
